import { Box } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import HelpCircleOutline from 'mdi-material-ui/HelpCircleOutline'
import RobotOutline from 'mdi-material-ui/RobotOutline'
import { useEffect } from 'react'
import { projectContext } from '../../data/action_context'
import { cardPopupService } from '../../services/card_popup_service'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { agentStateDescription } from '../../services/agents/card_agent_state'
import { useProjectAgentState } from '../hooks/use_agent_acknowledgements'
import { useActiveActionRunsForContext } from '../hooks/use_action_runs'
import { MovableFab } from '../movable_fab'

const PROJECT_CONTEXT = projectContext()

/** Project-wide free-form agent launcher, movable anywhere in application viewport. */
export function AgentChatFab() {
    const agentState = useProjectAgentState()
    const activeRuns = useActiveActionRunsForContext(PROJECT_CONTEXT)
    const isWaiting = activeRuns.some(({ status }) => status === 'waitingForInput')
        || agentState === 'waiting for input'
    const isRunning = !isWaiting && (
        activeRuns.some(({ status }) => status === 'running')
        || agentState === 'running'
    )
    const isQueued = !isWaiting && !isRunning && activeRuns.some(({ status }) => status === 'queued')
    const isUnseen = !isQueued && !isWaiting && !isRunning && agentState === 'unseen result'
    const stateDescription = isQueued
        ? 'Action is queued'
        : isWaiting
            ? agentStateDescription('waiting for input')
            : isRunning && agentState !== 'running'
                ? 'Action is running'
                : agentStateDescription(agentState)
    const label = stateDescription ? `Project agent â€” ${stateDescription}` : 'Project agent'
    const handleActivate = (nextAnchorElement: HTMLElement) => cardPopupService.toggleAction(PROJECT_CONTEXT, nextAnchorElement)
    const handleDragStart = () => cardPopupService.closeAction(PROJECT_CONTEXT)

    useEffect(() => {
        void dataService.listAgentConversations(PROJECT_CONTEXT).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Could not load project agent conversations' })
        })
    }, [])

    return (
        <>
            <MovableFab
                ariaLabel={label}
                fabSx={(theme) => ({
                    bgcolor: isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    isolation: 'isolate',
                    overflow: 'visible',
                    position: 'relative',
                    ...(isRunning && {
                        '@keyframes md2-project-run-spin': { to: { transform: 'rotate(1turn)' } },
                        '&::before': {
                            animation: 'md2-project-run-spin 1s linear infinite',
                            background: `conic-gradient(from 0deg, ${theme.palette.primary.main}, transparent 55%)`,
                            borderRadius: '50%',
                            content: '""',
                            inset: -4,
                            pointerEvents: 'none',
                            position: 'absolute',
                            zIndex: -1,
                        },
                    }),
                })}
                onActivate={handleActivate}
                onDragStart={handleDragStart}
                tooltip={label}
            >
                <Box component="span" sx={{ alignItems: 'center', display: 'inline-flex', position: 'relative' }}>
                    <RobotOutline />
                    {isWaiting ? (
                        <HelpCircleOutline sx={{ color: 'warning.contrastText', fontSize: 15, position: 'absolute', right: -9, top: -9 }} />
                    ) : null}
                    {isUnseen ? (
                        <Circle sx={{ color: 'info.contrastText', fontSize: 9, position: 'absolute', right: -7, top: -7 }} />
                    ) : null}
                </Box>
            </MovableFab>
        </>
    )
}

import { Box, Fab, Tooltip } from '@mui/material';
import type { SxProps, Theme } from '@mui/material';
import { useCallback, useEffect, useRef, useState } from 'react';
import type { MouseEvent, ReactNode, PointerEvent as ReactPointerEvent } from 'react';

const FAB_MARGIN = 16;
const FAB_SIZE = 56;
const DRAG_THRESHOLD = 5;

interface FabPosition {
    left: number;
    top: number;
}

interface DragState extends FabPosition {
    dragged: boolean;
    pointerId: number;
    startX: number;
    startY: number;
}

interface MovableFabProps {
    ariaLabel: string;
    children: ReactNode;
    disabled?: boolean;
    fabSx?: SxProps<Theme>;
    onActivate: (anchorElement: HTMLElement) => void;
    onDragStart?: () => void;
    tooltip: string;
}

function initialPosition(): FabPosition {
    return clampPosition(window.innerWidth - FAB_SIZE - FAB_MARGIN, window.innerHeight - FAB_SIZE - FAB_MARGIN);
}

function clampAxisPosition(position: number, viewportSize: number) {
    const availableSpace = Math.max(0, viewportSize - FAB_SIZE);
    const margin = Math.min(FAB_MARGIN, availableSpace / 2);

    return Math.min(Math.max(position, margin), availableSpace - margin);
}

function clampPosition(left: number, top: number): FabPosition {
    return {
        left: clampAxisPosition(left, window.innerWidth),
        top: clampAxisPosition(top, window.innerHeight),
    };
}

/** Primary floating launcher with viewport-bounded pointer dragging and click-after-drag suppression. */
export function MovableFab({ ariaLabel, children, disabled = false, fabSx, onActivate, onDragStart, tooltip }: MovableFabProps) {
    const [position, setPosition] = useState(initialPosition);
    const dragRef = useRef<DragState | null>(null);
    const handleResize = useCallback(() => {
        setPosition((current) => {
            const clamped = clampPosition(current.left, current.top);

            return clamped.left === current.left && clamped.top === current.top ? current : clamped;
        });
    }, []);

    useEffect(() => {
        window.addEventListener('resize', handleResize);

        return () => window.removeEventListener('resize', handleResize);
    }, [handleResize]);

    const handlePointerDown = (event: ReactPointerEvent<HTMLButtonElement>) => {
        dragRef.current = {
            ...position,
            dragged: false,
            pointerId: event.pointerId,
            startX: event.clientX,
            startY: event.clientY,
        };
        event.currentTarget.setPointerCapture?.(event.pointerId);
    };

    const handlePointerMove = (event: ReactPointerEvent<HTMLButtonElement>) => {
        const drag = dragRef.current;
        if (!drag || drag.pointerId !== event.pointerId) return;

        const deltaX = event.clientX - drag.startX;
        const deltaY = event.clientY - drag.startY;
        if (!drag.dragged && Math.hypot(deltaX, deltaY) < DRAG_THRESHOLD) return;
        if (!drag.dragged) onDragStart?.();

        drag.dragged = true;
        setPosition(clampPosition(drag.left + deltaX, drag.top + deltaY));
    };

    const handlePointerUp = (event: ReactPointerEvent<HTMLButtonElement>) => {
        if (dragRef.current?.pointerId !== event.pointerId) return;
        event.currentTarget.releasePointerCapture?.(event.pointerId);
    };

    const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
        if (dragRef.current?.dragged) {
            event.preventDefault();
            dragRef.current = null;

            return;
        }

        dragRef.current = null;
        onActivate(event.currentTarget);
    };

    return (
        <Tooltip title={tooltip}>
            <Box
                component="span"
                data-testid="movable-fab-position"
                sx={{ left: position.left, position: 'fixed', top: position.top, touchAction: 'none', zIndex: 'appBar' }}
            >
                <Fab
                    aria-label={ariaLabel}
                    color="primary"
                    disabled={disabled}
                    onClick={handleClick}
                    onPointerDown={handlePointerDown}
                    onPointerMove={handlePointerMove}
                    onPointerUp={handlePointerUp}
                    sx={fabSx}
                >
                    {children}
                </Fab>
            </Box>
        </Tooltip>
    );
}

import type { AgentConversation } from '../../data/data_types'

export type CardAgentState = 'idle' | 'running' | 'unseen result' | 'waiting for input'

/** Newest not-yet-viewed conversation for one action, or null when all are viewed. */
export function latestUnseenConversation(conversations: AgentConversation[], actionId: string) {
    return [...conversations]
        .filter((conversation) => conversation.actionId === actionId && !conversation.viewed)
        .sort((left, right) => right.startedAt.localeCompare(left.startedAt))[0] ?? null
}

/** True when any conversation has not been viewed yet. */
export function hasUnseenConversation(conversations: AgentConversation[]) {
    return conversations.some(({ viewed }) => !viewed)
}

function isConversationWaiting(conversations: AgentConversation[]) {
    return conversations.some(({ status }) => status === 'waitingForInput')
}

/** True when the card has at least one agent conversation still running. */
export function hasRunningConversation(conversations: AgentConversation[]) {
    return conversations.some((conversation) => (
        conversation.status === 'running' || conversation.status === 'waitingForInput'
    ))
}

/** Resolve the single agent state shown for a card, mirroring the priority waiting > running > unseen > idle. */
export function cardAgentState(conversations: AgentConversation[]): CardAgentState {
    if (isConversationWaiting(conversations)) return 'waiting for input'
    if (hasRunningConversation(conversations)) return 'running'
    if (hasUnseenConversation(conversations)) return 'unseen result'

    return 'idle'
}

/** Human-readable description of an agent state, or null when idle. */
export function agentStateDescription(agentState: CardAgentState): string | null {
    if (agentState === 'waiting for input') return 'Agent is waiting for input'
    if (agentState === 'running') return 'Agent is running'
    if (agentState === 'unseen result') return 'New agent result available'

    return null
}

import { useCallback, useSyncExternalStore } from 'react'
import { actionContextIdentity, type ActionContext } from '../../data/action_context'
import { actionRunRegistry, type ActionRun, type ActionRunStore } from '../../services/actions/action_run_registry'
import type { ActionRunBindingStore } from '../actions/run/state/action_run_binding_store'

const EMPTY_ACTIVE_RUNS: ReturnType<typeof actionRunRegistry.getGlobalActiveSnapshot> = []
const EMPTY_RUN_STORES: ActionRunStore[] = []
const subscribeEmpty = () => () => undefined
const getNullSnapshot = () => null

function useRunStore<T>(store: ActionRunStore | null, selector: (run: ActionRun | null) => T) {
    return useSyncExternalStore(
        store?.subscribe ?? subscribeEmpty,
        () => selector(store?.getSnapshot() ?? null),
        () => selector(null),
    )
}

function useActionRunStore(actionId: string, context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeActionRunByKey(actionId, contextIdentity, listener),
        [actionId, contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getActionRunStoreByKey(actionId, contextIdentity),
        [actionId, contextIdentity],
    )
    const store = useSyncExternalStore(
        subscribe,
        getSnapshot,
        getNullSnapshot,
    )

    return store
}

/** Subscribe to only the latest run bound to one root action and context. */
export function useActionRun(actionId: string, context: ActionContext) {
    const store = useActionRunStore(actionId, context)

    return useRunStore(store, (run) => run)
}

/** Subscribe to one selected value from a scoped action run. */
export function useActionRunSelector<T>(actionId: string, context: ActionContext, selector: (run: ActionRun | null) => T) {
    const store = useActionRunStore(actionId, context)

    return useRunStore(store, selector)
}

/** Subscribe to one selected value from a run identified by runId. */
export function useRunSelector<T>(runId: string | null, selector: (run: ActionRun | null) => T) {
    const subscribe = useCallback(
        (listener: () => void) => runId ? actionRunRegistry.subscribeRun(runId, listener) : subscribeEmpty(),
        [runId],
    )
    const getSnapshot = useCallback(
        () => selector(runId ? actionRunRegistry.getRunStore(runId)?.getSnapshot() ?? null : null),
        [runId, selector],
    )

    return useSyncExternalStore(subscribe, getSnapshot, () => selector(null))
}

/** Subscribe to runId selected by one popup runtime. */
export function useBoundRunId(bindingStore: ActionRunBindingStore) {
    return useSyncExternalStore(bindingStore.subscribe, bindingStore.getSnapshot, bindingStore.getSnapshot)
}

/** Subscribe to all live run stores for one root action and context. */
export function useActionRunStores(actionId: string, context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeActionRunByKey(actionId, contextIdentity, listener),
        [actionId, contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getActionRunStoresByKey(actionId, contextIdentity),
        [actionId, contextIdentity],
    )

    return useSyncExternalStore(subscribe, getSnapshot, () => EMPTY_RUN_STORES)
}

/** Subscribe to active run status summaries for one context. */
export function useActiveActionRunsForContext(context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeContextActiveByKey(contextIdentity, listener),
        [contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getContextActiveSnapshotByKey(contextIdentity),
        [contextIdentity],
    )

    return useSyncExternalStore(
        subscribe,
        getSnapshot,
        () => EMPTY_ACTIVE_RUNS,
    )
}

export function useRunningActionForContext(context: ActionContext) {
    return useActiveActionRunsForContext(context)[0] ?? null
}

/** Subscribe to the global active-run aggregate used by the global indicator. */
export function useActiveActionRuns() {
    return useSyncExternalStore(
        actionRunRegistry.subscribeGlobalActive,
        actionRunRegistry.getGlobalActiveSnapshot,
        actionRunRegistry.getGlobalActiveSnapshot,
    )
}

import { useCallback, useSyncExternalStore } from 'react'
import {
    actionAcknowledgementEvent,
    agentAcknowledgementService,
    cardAcknowledgementEvent,
    PROJECT_ACKNOWLEDGEMENT_EVENT,
} from '../../services/agents/agent_acknowledgement_service'
import { cardAgentState, latestUnseenConversation } from '../../services/agents/card_agent_state'
import { dataService } from '../../services/data/data_service'

function subscribeToAcknowledgements(eventTypes: string[], onStoreChange: () => void) {
    for (const eventType of eventTypes) agentAcknowledgementService.addEventListener(eventType, onStoreChange)

    return () => {
        for (const eventType of eventTypes) agentAcknowledgementService.removeEventListener(eventType, onStoreChange)
    }
}

/** Reads the live conversations of a card, which a rendered card copy cannot provide. */
export function cardConversations(cardInternalId: string | null | undefined) {
    return cardInternalId ? dataService.agents.getAgentConversations(cardInternalId) : []
}

/**
 * Agent state of one card, refreshed on that card's scoped conversation events.
 * Conversations are read from the agent store on every snapshot, so newly attached or
 * acknowledged conversations are picked up without republishing the card.
 */
export function useCardAgentState(cardInternalId: string | null | undefined) {
    const subscribe = useCallback((onStoreChange: () => void) => (
        cardInternalId
            ? subscribeToAcknowledgements([cardAcknowledgementEvent(cardInternalId)], onStoreChange)
            : () => undefined
    ), [cardInternalId])
    const getSnapshot = useCallback(() => cardAgentState(cardConversations(cardInternalId)), [cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Project agent state backed by project-origin conversations in AgentIntegration. */
export function useProjectAgentState() {
    const subscribe = useCallback((onStoreChange: () => void) => (
        subscribeToAcknowledgements([PROJECT_ACKNOWLEDGEMENT_EVENT], onStoreChange)
    ), [])
    const getSnapshot = useCallback(() => (
        cardAgentState(dataService.agents.getProjectAgentConversationsSnapshot())
    ), [])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Agent state of one card action, refreshed only by that action's scoped conversation event. */
export function useActionAgentState(cardInternalId: string | null | undefined, actionId: string) {
    const subscribe = useCallback((onStoreChange: () => void) => (
        cardInternalId
            ? subscribeToAcknowledgements([actionAcknowledgementEvent(cardInternalId, actionId)], onStoreChange)
            : () => undefined
    ), [actionId, cardInternalId])
    const getSnapshot = useCallback(() => cardAgentState(
        cardConversations(cardInternalId).filter((conversation) => conversation.actionId === actionId),
    ), [actionId, cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Identifies the unseen conversations of the given card actions, refreshed on their scoped events. */
export function useActionsUnseenKey(cardInternalId: string | null | undefined, actionIds: string[]) {
    const actionIdsKey = [...new Set(actionIds)].sort().join(',')
    const subscribe = useCallback((onStoreChange: () => void) => {
        if (!cardInternalId) return () => undefined
        const eventTypes = actionIdsKey.split(',')
            .filter((actionId) => actionId.length > 0)
            .map((actionId) => actionAcknowledgementEvent(cardInternalId, actionId))

        return subscribeToAcknowledgements(eventTypes, onStoreChange)
    }, [actionIdsKey, cardInternalId])
    const getSnapshot = useCallback(() => {
        const conversations = cardConversations(cardInternalId)

        return actionIdsKey.split(',')
            .map((actionId) => latestUnseenConversation(conversations, actionId)?.id ?? '')
            .join(',')
    }, [actionIdsKey, cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

import { ACTION_APPLIES_TO_FIELDS, CUSTOM_PROMPT_ACTION_ID } from './action_types'
import type { ActionAppliesToField, ActionDefinition } from './action_types'
import type { Card, CardHeader, CardTypeConfig } from './data_types'
